import {
  Input,
  InputGroup,
  InputRightElement,
  FormControl,
  FormLabel,
  Button,
  VStack,
  useToast,
  Box,
  Text,
  Flex,
} from "@chakra-ui/react";
import { useState } from "react";
import { useHistory } from "react-router-dom";
import axios from "axios";
import { ChatState } from "../../Context/ChatProvider";

const Login = () => {
  const [show, setShow] = useState(false);
  const handleClick = () => setShow(!show);
  const [email, setEmail] = useState();
  const [password, setPassword] = useState();
  const [loading, setLoading] = useState(false);

  const toast = useToast();
  const history = useHistory();
  const { setUser } = ChatState();

  const submitHandler = async () => {
    setLoading(true);
    if (!email || !password) {
      toast({
        title: "Please Fill all the Fields",
        status: "warning",
        duration: 5000,
        isClosable: true,
        position: "bottom",
      });
      setLoading(false);
      return;
    }

    try {
      const config = {
        headers: {
          "Content-type": "application/json",
        },
      };

      const { data } = await axios.post(
        "/api/user/login",
        { email, password },
        config
      );

      toast({
        title: "Login Successful",
        status: "success",
        duration: 5000,
        isClosable: true,
        position: "bottom",
      });

      setUser(data);
      localStorage.setItem("userInfo", JSON.stringify(data));
      setLoading(false);
      history.push("/chats");
    } catch (error) {
      toast({
        title: "Error Occurred!",
        description: error.response?.data?.message || error.message,
        status: "error",
        duration: 5000,
        isClosable: true,
        position: "bottom",
      });
      setLoading(false);
    }
  };

  return (
    <Flex minH="50vh" align="center" justify="center" p={4}>
      <Box
        bg="rgba(255, 255, 255, 0.95)"
        backdropFilter="blur(10px)"
        borderRadius="20px"
        p={8}
        boxShadow="0 20px 40px rgba(0, 0, 0, 0.1)"
        border="1px solid rgba(255, 255, 255, 0.2)"
        maxW="400px"
        w="100%"
      >
        <VStack spacing="20px">
          <FormControl id="email" isRequired>
            <FormLabel fontSize="sm" fontWeight="600" color="gray.700" mb={2}>
              Email Address <Text as="span" color="red.500">*</Text>
            </FormLabel>
            <Input
              value={email}
              type="email"
              placeholder="Enter Your Email Address"
              onChange={(e) => setEmail(e.target.value)}
              bg="gray.50"
              border="1px solid"
              borderColor="gray.200"
              borderRadius="12px"
              h="50px"
              fontSize="sm"
              _hover={{ borderColor: "blue.300", bg: "white" }}
              _focus={{
                borderColor: "blue.500",
                bg: "white",
                boxShadow: "0 0 0 3px rgba(66, 153, 225, 0.1)",
              }}
            />
          </FormControl>

          <FormControl id="password" isRequired>
            <FormLabel fontSize="sm" fontWeight="600" color="gray.700" mb={2}>
              Password <Text as="span" color="red.500">*</Text>
            </FormLabel>
            <InputGroup size="md">
              <Input
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                type={show ? "text" : "password"}
                placeholder="Enter password"
                bg="gray.50"
                border="1px solid"
                borderColor="gray.200"
                borderRadius="12px"
                h="50px"
                fontSize="sm"
                pr="4.5rem"
                _hover={{ borderColor: "blue.300", bg: "white" }}
                _focus={{
                  borderColor: "blue.500",
                  bg: "white",
                  boxShadow: "0 0 0 3px rgba(66, 153, 225, 0.1)",
                }}
              />
              <InputRightElement width="4.5rem" h="50px">
                <Button
                  h="32px"
                  size="sm"
                  onClick={handleClick}
                  variant="ghost"
                  color="gray.600"
                  fontSize="xs"
                  fontWeight="500"
                  _hover={{ bg: "gray.100" }}
                >
                  {show ? "Hide" : "Show"}
                </Button>
